// Filter: only process .csv files
const file = $json;
if (!file.name || !file.name.toLowerCase().endsWith('.csv')) {
  return [];
}
return [{ json: file }];

// Parse X Analytics CSV → analytics_events rows
// X Analytics CSV columns (typical export):
//   Tweet id, Tweet permalink, Tweet text, Time, Impressions, Engagements,
//   Engagement rate, Retweets, Replies, Likes, Profile clicks, ...
//
// Refs: docs/specs/devrel-analytics-stack.md (AC-8)
const content = Buffer.from($json.data, 'base64').toString('utf-8');
const lines = content.split('\n').filter(l => l.trim());
if (lines.length < 2) return [];

// Parse header
const header = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, '').toLowerCase());

const findCol = (candidates) => {
  for (const c of candidates) {
    const idx = header.findIndex(h => h.includes(c));
    if (idx >= 0) return idx;
  }
  return -1;
};

const idxTweetId     = findCol(['tweet id', 'id']);
const idxTime        = findCol(['time', 'date']);
const idxImpressions = findCol(['impressions']);
const idxEngagements = findCol(['engagements']);
const idxLikes       = findCol(['likes', 'favorites']);
const idxRetweets    = findCol(['retweets']);
const idxReplies     = findCol(['replies']);

const rows = [];
for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(',').map(c => c.trim().replace(/^"|"$/g, ''));
  if (cols.length < 3) continue;

  const tweetId = idxTweetId >= 0 ? cols[idxTweetId] : `row-${i}`;
  const contentId = `twitter:${tweetId}`;
  const occurredAt = idxTime >= 0 && cols[idxTime]
    ? new Date(cols[idxTime]).toISOString()
    : new Date().toISOString();

  const addRow = (eventType, colIdx) => {
    if (colIdx < 0) return;
    const val = parseFloat(cols[colIdx]);
    if (isNaN(val)) return;
    rows.push({
      platform: 'twitter',
      content_id: contentId,
      event_type: eventType,
      occurred_at: occurredAt,
      metric_value: val,
      metadata: JSON.stringify({ source: 'x_csv_export', tweet_id: tweetId })
    });
  };

  addRow('impression', idxImpressions);
  addRow('engagement', idxEngagements);
  addRow('like', idxLikes);
  addRow('retweet', idxRetweets);
  addRow('reply', idxReplies);
}

return rows.map(r => ({ json: r }));

// Move processed CSV to archive folder to avoid re-processing
const path = require('path');
const fs = require('fs');
const src = $('Read CSV File').first().json.path;
if (!src) return [{ json: { archived: false } }];
const archiveDir = path.join(path.dirname(src), 'processed');
if (!fs.existsSync(archiveDir)) fs.mkdirSync(archiveDir, { recursive: true });
const dst = path.join(archiveDir, path.basename(src));
try { fs.renameSync(src, dst); } catch(e) { /* ignore — file may already be moved */ }
return [{ json: { archived: true, src, dst } }];
